<?php
require_once __DIR__ . '/_bootstrap.php'; customerPostCsrf(); $notice='';
if($_SERVER['REQUEST_METHOD']==='POST'){ $id=(int)($_POST['product_id']??0);$qty=max(0,(int)($_POST['quantity']??1)); if($id){ if($qty===0) customerQuery('DELETE FROM cart_items WHERE user_id=? AND product_id=?',[$customerId,$id]); else customerQuery('INSERT INTO cart_items (user_id,product_id,quantity) VALUES (?,?,?) ON DUPLICATE KEY UPDATE quantity=VALUES(quantity)',[$customerId,$id,$qty]); $notice='Cart updated.';}}
$items=customerRows("SELECT ci.product_id,ci.quantity,p.name,p.retail_price,p.sku,(ci.quantity*p.retail_price) subtotal FROM cart_items ci JOIN products p ON p.id=ci.product_id WHERE ci.user_id=? ORDER BY ci.id DESC",[$customerId]);$total=array_sum(array_map(fn($i)=>(float)$i['subtotal'],$items)); customerPageStart('Shopping cart','');?><div class="cw-title"><div><h1>Shopping cart</h1><p>Review your items before checkout.</p></div></div><?php if($notice):?><div class="cw-alert"><?=e($notice)?></div><?php endif;?><div class="cw-grid cw-grid-2"><section class="cw-card"><?php if(!$items):?><div class="cw-empty">Your cart is empty. <a href="<?=e(BASE_URL)?>/shop/products.php">Browse products →</a></div><?php else:?><table class="cw-table"><tr><th>Product</th><th>Qty</th><th>Price</th><th></th></tr><?php foreach($items as $i):?><tr><td><strong><?=e($i['name'])?></strong><br><span class="muted"><?=e($i['sku'])?></span></td><td><form method="post"><?=csrfField()?><input type="hidden" name="product_id" value="<?= (int)$i['product_id']?>"><input style="width:70px" type="number" min="0" name="quantity" value="<?= (int)$i['quantity']?>" onchange="this.form.submit()"></form></td><td><?=e(formatPrice($i['subtotal']))?></td><td><form method="post"><?=csrfField()?><input type="hidden" name="product_id" value="<?= (int)$i['product_id']?>"><input type="hidden" name="quantity" value="0"><button class="cw-btn alt" type="submit">Remove</button></form></td></tr><?php endforeach;?></table><?php endif;?></section><aside class="cw-card"><h2>Summary</h2><p>Subtotal <strong style="float:right"><?=e(formatPrice($total))?></strong></p><hr><p><strong>Total</strong><strong style="float:right"><?=e(formatPrice($total))?></strong></p><?php if($items):?><a class="cw-btn gold" href="checkout.php">Proceed to checkout</a><?php endif;?></aside></div><?php customerPageEnd();?>